import React from "react";
import myImage from "../img/myImage.png";

class About extends React.Component {
  constructor() {
    super();
    this.state = {
      skills: [
        { id: "HTML5_skill", content: "HTML5 / CSS3", porcentage: "85%", value: "85" },
        { id: "JavaScript_skill", content: "JavaScript (ES6+)", porcentage: "90%", value: "90" },
        { id: "ReactJS_skill", content: "React.js", porcentage: "90%", value: "90" },
        { id: "NodeJS_skill", content: "Node.js / Express", porcentage: "80%", value: "80" },
        { id: "Database_skill", content: "PostgreSQL / MongoDB / ClickHouse", porcentage: "75%", value: "75" },
        { id: "Cloud_skill", content: "AWS & Scalable Architectures", porcentage: "85%", value: "85" },
        { id: "UIUX_skill", content: "UI/UX Dashboards & Animations", porcentage: "85%", value: "85" },
        { id: "Git_skill", content: "Git Workflows & Automation", porcentage: "90%", value: "90" }
      ],
      about_me: [
        {
          id: "first-p-about",
          content:
            "I’m Ehtesham Alam, a Full Stack Developer and Assistant Manager – Mobility Solutions at Mahindra Last Mile Mobility. I specialize in building scalable, efficient, and user‑friendly digital solutions that bridge mobility and modern software."
        },
        {
          id: "second-p-about",
          content:
            "I bring hands‑on expertise in React, Node.js, Express, and cloud‑based architectures, with a strong focus on polished UI/UX dashboards, workflow automation, and real‑time data systems."
        },
        {
          id: "third-p-about",
          content:
            "I hold a B.Tech in Computer Science (NIT Warangal, Class of 2025) and completed a research internship at IIT ISM Dhanbad, where I contributed to real‑time emotion detection systems."
        }
      ]
    };
  }

  render() {
    return (
      <section id="about" className="about-mf sect-pt4 route about-section">
        <div className="container">
          <div className="row justify-content-center">
            <div className="col-lg-10">
              <div className="box-shadow-full about-card">
                <div className="row">
                  {/* Left column: Image + Skills */}
                  <div className="col-md-5 text-center mb-4 mb-md-0">
                    <div className="about-img mb-4">
                      <img
                        src={myImage}
                        className="img-fluid rounded-circle shadow-lg profile-img"
                        alt="Ehtesham Alam"
                      />
                    </div>
                    <div className="skill-mf">
                      {this.state.skills.map(skill => (
                        <React.Fragment key={skill.id}>
                          <div className="d-flex justify-content-between">
                            <span className="glow-label">{skill.content}</span>
                            <span className="gradient-text">{skill.porcentage}</span>
                          </div>
                          <div className="progress">
                            <div
                              className="progress-bar progress-bar-striped progress-bar-animated gradient-skill"
                              role="progressbar"
                              style={{ width: skill.porcentage }}
                              aria-valuenow={skill.value}
                              aria-valuemin="0"
                              aria-valuemax="100"
                            ></div>
                          </div>
                        </React.Fragment>
                      ))}
                    </div>
                  </div>

                  {/* Right column: About Me */}
                  <div className="col-md-7">
                    <div className="about-me">
                      <div className="title-box-2 mb-4">
                        <h5 className="title-left gradient-text">About Me</h5>
                      </div>
                      {this.state.about_me.map(content => (
                        <p className="lead glow-text mb-3" key={content.id}>
                          {content.content}
                        </p>
                      ))}
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </section>
    );
  }
}

export default About;
